import{_ as e,o as a,c as t,ae as o}from"./chunks/framework.Bwt6MOeu.js";const h=JSON.parse('{"title":"Provider Capability Routing","description":"","frontmatter":{},"headers":[],"relativePath":"guide/provider-capability-routing.md","filePath":"guide/provider-capability-routing.md"}'),r={name:"guide/provider-capability-routing.md"};function n(l,i,c,p,d,s){return a(),t("div",null,[...i[0]||(i[0]=[o('<h1 id="provider-capability-routing" tabindex="-1">Provider Capability Routing <a class="header-anchor" href="#provider-capability-routing" aria-label="Permalink to &quot;Provider Capability Routing&quot;">​</a></h1><p>Provider connections are not separate product islands. They are capability routes inside one SocioProphet system.</p><h2 id="capability-model" tabindex="-1">Capability model <a class="header-anchor" href="#capability-model" aria-label="Permalink to &quot;Capability model&quot;">​</a></h2><p>Each provider maps to one or more capabilities:</p><ul><li>coding</li><li>research</li><li>browsing</li><li>local execution</li><li>recovery / fallback</li></ul><p>A provider is therefore not just a logo or an API key. It is a capability endpoint with health, scope, and routing semantics.</p><h2 id="routing-principles" tabindex="-1">Routing principles <a class="header-anchor" href="#routing-principles" aria-label="Permalink to &quot;Routing principles&quot;">​</a></h2><p>Capability routing follows a few public-facing principles:</p><h3 id="one-platform-identity" tabindex="-1">One platform identity <a class="header-anchor" href="#one-platform-identity" aria-label="Permalink to &quot;One platform identity&quot;">​</a></h3><p>The user signs in once to SocioProphet.</p><h3 id="explicit-provider-state" tabindex="-1">Explicit provider state <a class="header-anchor" href="#explicit-provider-state" aria-label="Permalink to &quot;Explicit provider state&quot;">​</a></h3><p>Each provider has a visible state:</p><ul><li>not connected</li><li>connecting</li><li>connected</li><li>needs re-auth</li><li>limited capability</li><li>failed test</li><li>revoked</li></ul><h3 id="graceful-degradation" tabindex="-1">Graceful degradation <a class="header-anchor" href="#graceful-degradation" aria-label="Permalink to &quot;Graceful degradation&quot;">​</a></h3><p>When a capability cannot execute through one provider, the system can route to fallback paths or present the correct recovery action.</p><h3 id="human-legible-explanation" tabindex="-1">Human-legible explanation <a class="header-anchor" href="#human-legible-explanation" aria-label="Permalink to &quot;Human-legible explanation&quot;">​</a></h3><p>Routing must never feel like unexplained black-box switching. The user must understand what is connected, what is usable, and what requires action.</p><h2 id="digital-surface-connection" tabindex="-1">Digital surface connection <a class="header-anchor" href="#digital-surface-connection" aria-label="Permalink to &quot;Digital surface connection&quot;">​</a></h2><p>The <code>.digital</code> surface is where provider capability routing becomes visible as part of public-facing trust and identity. Digital trust is not only presentation. It is also the governed connection between identity, capability, and recoverability.</p>',19)])])}const b=e(r,[["render",n]]);export{h as __pageData,b as default};
